svg.script:

(function() {
  // Dados estritos deterministicos de cada etapa temporal (0-4)
  var stepsData = [
    {
      progress: 80,
      color: "var(--fm1p7-coral, #ef4444)",
      cortexTitle: "Córtex Motor / Trato Corticospinal (1º NMS)",
      cortexStatus: "Status: ISQUEMIA AGUDA / Interrupção súbita do drive descendente (0-30 min)",
      tractLabel: "Drive Descendente: 0% (Silêncio Cortical Agudo)",
      medulaTitle: "ESTADO MEDULAR: CHOQUE ESPINAL / DIASSQUISE AGUDA",
      medulaDesc: "Perda súbita da facilitação descendente. Motoneurônios alfa hipoexcitáveis.",
      muscleStatus: "Tônus Muscular: Flácido (Atonia ou Hipotonia Severa)",
      tonusVal: "0 / 4+ (Atonia / Flacidez)",
      tonusBarWidth: 12,
      tonusDesc: "Flacidez completa. Resistência passiva ausente. Simulador de 2º NMS!",
      reflexVal: "0 / 4+ (Arreflexia)",
      reflexBarWidth: 12,
      babinski: "Ausente ou Indeterminado",
      babinskiColor: "var(--fm1p7-amber, #f59e0b)",
      clonus: "Ausente",
      clonusColor: "var(--fm1p7-text-muted, #94a3b8)",
      alertTitle: "🚨 DIAGNÓSTICO TOPOGRÁFICO: FALSO 2º NEURÔNIO MOTOR",
      alertLine1: "• CUIDADO NA PROVA: O déficit motor agudo com flacidez NÃO indica lesão periférica/2º NMS.",
      alertLine2: "• Fisiopatologia: Choque espinal por perda súbita do drive trófico supraespinal.",
      alertAction: "👉 CONDUTA: Mantenha a suspeita de AVE/Trauma Medular! A espasticidade virá depois.",
      alertBg: "var(--fm1p7-coral-bg, rgba(239,68,68,0.12))",
      alertBorder: "var(--fm1p7-coral, #ef4444)",
      alertTitleColor: "var(--fm1p7-coral, #ef4444)"
    },
    {
      progress: 240,
      color: "var(--fm1p7-amber, #f59e0b)",
      cortexTitle: "Córtex Motor / Trato Corticospinal (1º NMS)",
      cortexStatus: "Status: Necrose focal estabelecida; edema peri-lesional (1-24 horas)",
      tractLabel: "Drive Descendente: 0% (Interrupção mantida)",
      medulaTitle: "ESTADO MEDULAR: TRANSIÇÃO E INÍCIO DA REORGANIZAÇÃO",
      medulaDesc: "Lenta recuperação da excitabilidade intrínseca interneuronada espinal.",
      muscleStatus: "Tônus Muscular: Flácido / Hipotônico em resolução",
      tonusVal: "1+ / 4+ (Hipotonia Leve)",
      tonusBarWidth: 45,
      tonusDesc: "Mínimo tônus detectável. Ausência de espasticidade nesta fase.",
      reflexVal: "1+ / 4+ (Hiporreflexia)",
      reflexBarWidth: 45,
      babinski: "Duvidoso / Em esboço",
      babinskiColor: "var(--fm1p7-amber, #f59e0b)",
      clonus: "Ausente",
      clonusColor: "var(--fm1p7-text-muted, #94a3b8)",
      alertTitle: "⚠️ JANELA DE TRANSIÇÃO: REORGANIZAÇÃO MEDULAR EM ANDAMENTO",
      alertLine1: "• O choque espinal começa a ceder nas primeiras 24 horas.",
      alertLine2: "• Brotamento sináptico denervacional inicia nos motoneurônios alfa.",
      alertAction: "👉 AVALIAÇÃO: Sinais piramidais ainda discretos. Não feche diagnóstico definitivo de reflexo.",
      alertBg: "var(--fm1p7-amber-bg, rgba(245,158,11,0.12))",
      alertBorder: "var(--fm1p7-amber, #f59e0b)",
      alertTitleColor: "var(--fm1p7-amber, #f59e0b)"
    },
    {
      progress: 400,
      color: "var(--fm1p7-teal, #14b8a6)",
      cortexTitle: "Córtex Motor / Trato Corticospinal (1º NMS)",
      cortexStatus: "Status: Cicatriz glial em formação; degeneração walleriana distal (1-7 dias)",
      tractLabel: "Drive Descendente: Ausente (Degeneração do Trato Descendente)",
      medulaTitle: "ESTADO MEDULAR: BROTAMENTO COLATERAL & HIPEREXCITABILIDADE",
      medulaDesc: "Receptores medulares hipersensíveis à denervação. Arco reflexo em desinibição.",
      muscleStatus: "Tônus Muscular: Reabastecimento Tônico (Normotonia -> Hipertonia)",
      tonusVal: "2+ / 4+ (Normotonia / Hipertonia Leve)",
      tonusBarWidth: 95,
      tonusDesc: "Retorno da resistência ao estiramento passivo. Início da liberação do arco reflexo.",
      reflexVal: "2+ a 3+ / 4+ (Normo a Hiperreflexia)",
      reflexBarWidth: 110,
      babinski: "PRESENTE (Reflexo Extensor +)",
      babinskiColor: "var(--fm1p7-teal, #14b8a6)",
      clonus: "Esgotável (1-3 batimentos)",
      clonusColor: "var(--fm1p7-teal, #14b8a6)",
      alertTitle: "⚡ ORGANIZAÇÃO PIRAMIDAL: O 1º NMS COMEÇA A SE REVELAR",
      alertLine1: "• Aparecimento inequívoco do Sinal de Babinski (Reflexo cutâneo-plantar extensor).",
      alertLine2: "• Hiperreflexia profundas instalando-se gradativamente nos membros afetados.",
      alertAction: "✅ CONFIRMAÇÃO: Topografia de 1º NMS (Central) consolida-se clinicamente!",
      alertBg: "var(--fm1p7-teal-bg, rgba(20,184,166,0.12))",
      alertBorder: "var(--fm1p7-teal, #14b8a6)",
      alertTitleColor: "var(--fm1p7-teal, #14b8a6)"
    },
    {
      progress: 560,
      color: "var(--fm1p7-indigo, #6366f1)",
      cortexTitle: "Córtex Motor / Trato Corticospinal (1º NMS)",
      cortexStatus: "Status: Lesão crônica consolidada; perda de inibição supraespinal (2-4 semanas)",
      tractLabel: "Drive Descendente: Inibição Cortical PERDIDA",
      medulaTitle: "ESTADO MEDULAR: HIPERATIVIDADE DO ARCO REFLEXO MIOTÁTICO",
      medulaDesc: "Loop miotático desinibido; hiperexcitabilidade de motoneurônios alfa e gama.",
      muscleStatus: "Tônus Muscular: ESPASTICIDADE EM MOLA DE CANIVETE",
      tonusVal: "3+ / 4+ (Hipertonia Espástica)",
      tonusBarWidth: 145,
      tonusDesc: "Resistência inicial rápida com liberação súbita (Sinal do Canivete). Padrão piramidal!",
      reflexVal: "3+ a 4+ / 4+ (Hiperreflexia Vivaz)",
      reflexBarWidth: 155,
      babinski: "PRESENTE (Clássico Extensor)",
      babinskiColor: "var(--fm1p7-indigo, #6366f1)",
      clonus: "Inesgotável / Vivaz",
      clonusColor: "var(--fm1p7-indigo, #6366f1)",
      alertTitle: "🛡️ SÍNDROME DO 1º NMS INSTALADA (ESPASTICIDADE)",
      alertLine1: "• Quadro clássico completo: Hipertonia espástica + Hiperreflexia + Babinski.",
      alertLine2: "• Ausência continuada de fasciculações confirma integridade do 2º NMS periférico.",
      alertAction: "✅ DIAGNÓSTICO DEFINITIVO: Síndrome Piramidal (1º NMS) Plena.",
      alertBg: "var(--fm1p7-indigo-bg, rgba(99,102,241,0.12))",
      alertBorder: "var(--fm1p7-indigo, #6366f1)",
      alertTitleColor: "var(--fm1p7-indigo, #6366f1)"
    },
    {
      progress: 720,
      color: "var(--fm1p7-indigo, #6366f1)",
      cortexTitle: "Córtex Motor / Trato Corticospinal (1º NMS)",
      cortexStatus: "Status: Sequela crônica estável; reorganização plástica máxima (> 1 mês)",
      tractLabel: "Drive Descendente: Sequela Piramidal Fixa",
      medulaTitle: "ESTADO MEDULAR: CIRCUITO ESPINAL CRÔNICO DEFINITIVO",
      medulaDesc: "Hiper-reflexia permanente por perda sustentada do controle inibitório piramidal.",
      muscleStatus: "Tônus Muscular: Espasticidade Crônica / Encurtamento Muscular",
      tonusVal: "4+ / 4+ (Espasticidade Grave / Rigidez Piramidal)",
      tonusBarWidth: 180,
      tonusDesc: "Hipertonia espástica fixa. Padrão flexor em membro superior / extensor em inferior.",
      reflexVal: "4+ / 4+ (Hiperreflexia + Clonus Inesgotável)",
      reflexBarWidth: 180,
      babinski: "PRESENTE + Sinal de Hoffmann (+)",
      babinskiColor: "var(--fm1p7-indigo, #6366f1)",
      clonus: "Clonus Inesgotável + Hoffmann (+)",
      clonusColor: "var(--fm1p7-indigo, #6366f1)",
      alertTitle: "🏛️ SÍNDROME PIRAMIDAL DEFINITIVA FIXADA",
      alertLine1: "• Estágio crônico final da lesão do 1º NMS. Espasticidade established.",
      alertLine2: "• Atrofia muscular pode surgir por DESUSO (nunca por denervação como no 2º NMS).",
      alertAction: "📌 CONSOLIDAÇÃO: Padrão definitivo para diferencial em provas de residência.",
      alertBg: "var(--fm1p7-indigo-bg, rgba(99,102,241,0.12))",
      alertBorder: "var(--fm1p7-indigo, #6366f1)",
      alertTitleColor: "var(--fm1p7-indigo, #6366f1)"
    }
  ];

  var currentStep = 0;

  function updateUI(step) {
    currentStep = step;
    var d = stepsData[step];

    // 1. Atualiza Barra de Progresso
    var progressBar = document.getElementById("fm1p7-progress-bar");
    if (progressBar) {
      progressBar.setAttribute("x2", d.progress);
      progressBar.setAttribute("stroke", d.color);
    }

    // 2. Atualiza Estilo dos Círculos dos Botões
    for (var i = 0; i < 5; i++) {
      var circle = document.getElementById("fm1p7-node-circle-" + i);
      if (circle) {
        if (i === step) {
          circle.setAttribute("fill", d.color);
          circle.setAttribute("r", "16");
          circle.setAttribute("filter", "url(#fm1p7-glow-indigo)");
        } else if (i < step) {
          circle.setAttribute("fill", "var(--fm1p7-card, #1e293b)");
          circle.setAttribute("r", "12");
          circle.removeAttribute("filter");
        } else {
          circle.setAttribute("fill", "var(--fm1p7-card, #1e293b)");
          circle.setAttribute("r", "12");
          circle.removeAttribute("filter");
        }
      }
    }

    // 3. Atualiza Painel Esquerdo (Diagrama)
    document.getElementById("fm1p7-cortex-title").textContent = d.cortexTitle;
    document.getElementById("fm1p7-cortex-status").textContent = d.cortexStatus;
    document.getElementById("fm1p7-cortex-status").setAttribute("fill", d.color);

    document.getElementById("fm1p7-spinal-tract-line").setAttribute("stroke", d.color);
    document.getElementById("fm1p7-spinal-arrow").setAttribute("fill", d.color);
    document.getElementById("fm1p7-tract-label").textContent = d.tractLabel;

    document.getElementById("fm1p7-medula-box").setAttribute("fill", d.alertBg);
    document.getElementById("fm1p7-medula-box").setAttribute("stroke", d.color);
    document.getElementById("fm1p7-medula-state-title").textContent = d.medulaTitle;
    document.getElementById("fm1p7-medula-state-title").setAttribute("fill", d.color);
    document.getElementById("fm1p7-medula-state-desc").textContent = d.medulaDesc;

    document.getElementById("fm1p7-muscle-status").textContent = d.muscleStatus;
    document.getElementById("fm1p7-muscle-status").setAttribute("fill", d.color);

    // 4. Atualiza Painel Direito (Achados Clínicos)
    document.getElementById("fm1p7-txt-tonus-val").textContent = d.tonusVal;
    document.getElementById("fm1p7-txt-tonus-val").setAttribute("fill", d.color);
    document.getElementById("fm1p7-bar-tonus").setAttribute("width", d.tonusBarWidth);
    document.getElementById("fm1p7-bar-tonus").setAttribute("fill", d.color);
    document.getElementById("fm1p7-tonus-desc").textContent = d.tonusDesc;

    document.getElementById("fm1p7-txt-reflex-val").textContent = d.reflexVal;
    document.getElementById("fm1p7-txt-reflex-val").setAttribute("fill", d.color);
    document.getElementById("fm1p7-bar-reflex").setAttribute("width", d.reflexBarWidth);
    document.getElementById("fm1p7-bar-reflex").setAttribute("fill", d.color);

    document.getElementById("fm1p7-txt-babinski").textContent = d.babinski;
    document.getElementById("fm1p7-txt-babinski").setAttribute("fill", d.babinskiColor);

    document.getElementById("fm1p7-txt-clonus").textContent = d.clonus;
    document.getElementById("fm1p7-txt-clonus").setAttribute("fill", d.clonusColor);

    // 5. Atualiza Caixa de Alerta / Topografia
    document.getElementById("fm1p7-alert-box").setAttribute("fill", d.alertBg);
    document.getElementById("fm1p7-alert-box").setAttribute("stroke", d.alertBorder);
    document.getElementById("fm1p7-alert-title").textContent = d.alertTitle;
    document.getElementById("fm1p7-alert-title").setAttribute("fill", d.alertTitleColor);
    document.getElementById("fm1p7-alert-line1").textContent = d.alertLine1;
    document.getElementById("fm1p7-alert-line2").textContent = d.alertLine2;
    document.getElementById("fm1p7-alert-action").textContent = d.alertAction;
  }

  // Event Listeners nos Botões da Timeline
  for (var i = 0; i < 5; i++) {
    (function(index) {
      var btn = document.getElementById("fm1p7-btn-step-" + index);
      if (btn) {
        btn.addEventListener("click", function() { updateUI(index); });
        btn.addEventListener("keydown", function(e) {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            updateUI(index);
          }
        });
      }
    })(i);
  }

  // Botões Anterior / Próximo
  var btnPrev = document.getElementById("fm1p7-btn-prev");
  if (btnPrev) {
    btnPrev.addEventListener("click", function() {
      if (currentStep > 0) updateUI(currentStep - 1);
    });
    btnPrev.addEventListener("keydown", function(e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        if (currentStep > 0) updateUI(currentStep - 1);
      }
    });
  }

  var btnNext = document.getElementById("fm1p7-btn-next");
  if (btnNext) {
    btnNext.addEventListener("click", function() {
      if (currentStep < 4) updateUI(currentStep + 1);
    });
    btnNext.addEventListener("keydown", function(e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        if (currentStep < 4) updateUI(currentStep + 1);
      }
    });
  }

  // Inicializa no Step 0 (Hiperagudo Flácido)
  updateUI(0);
})();
